ns/BO4WNWgw6wKSeQBeNLzbSpkuNkbBoypLeJkBXSqS.jpg','2026-05-20 23:11:26','2026-05-20 23:11:26'),(2142,179,'LATUNISEXFINEJERSEYTEE6901-48',11.00,NULL,100,'{\"size\":\"S\",\"color\":\"White\"}','products/variations/uORMAX74ILXQjgZxDqPaBdYNGiUhY9ZRi4UTuOj1.jpg','2026-05-20 23:11:26','2026-05-20 23:11:26'),(2143,179,'LATUNISEXFINEJERSEYTEE6901-49',11.00,NULL,100,'{\"size\":\"XL\",\"color\":\"White\"}','products/variations/6SwXyWkIGwggwn1bosxKVr7QmeWUX7ztgFawceOL.jpg','2026-05-20 23:11:26','2026-05-20 23:11:26');
