--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `category_id` bigint unsigned NOT NULL,
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'simple',
  `variation_attribute_defs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sku` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `price` decimal(10,2) DEFAULT NULL,
  `compare_at_price` decimal(10,2) DEFAULT NULL,
  `stock_quantity` int unsigned NOT NULL DEFAULT '0',
  `image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gallery` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_featured` tinyint(1) NOT NULL DEFAULT '0',
  `is_customizable` tinyint(1) NOT NULL DEFAULT '0',
  `custom_print_area` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `products_slug_unique` (`slug`),
  UNIQUE KEY `products_sku_unique` (`sku`),
  KEY `products_category_id_foreign` (`category_id`),
  CONSTRAINT `products_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE CASCADE,
  CONSTRAINT `products_chk_1` CHECK (json_valid(`variation_attribute_defs`)),
  CONSTRAINT `products_chk_2` CHECK (json_valid(`gallery`)),
  CONSTRAINT `products_chk_3` CHECK (json_valid(`custom_print_area`))
) ENGINE=InnoDB AUTO_INCREMENT=180 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `products`
--

LOCK TABLES `products` WRITE;
/*!40000 ALTER TABLE `products` DISABLE KEYS */;
INSERT INTO `products` VALUES (10,5,'variable','[{\"key\":\"size\",\"label\":\"Size\",\"values\":[\"L\",\"M\",\"S\"]},{\"key\":\"color\",\"label\":\"Color\",\"values\":[\"White\"]}]','All-Over Print Beanie','all-over-print-beanie','ALLOVERPRINTBEANIE','This soft double-layered All-Over Print Beanie is yours to customize from A to Z. Put your exceptional designs on this headwear, add a custom label, and watch your customers wear it with their heads held high.\r\n\r\nFabric composition in the EU: 96% polyester, 4% spandex\r\nFabric composition in the US: 93% polyester, 7% spandex\r\nFabric weight in the EU: 6.34 oz./yd.² (215 g/m²)\r\nFabric weight in the US: 7.08 oz./yd.² (240 g/m²)\r\nDouble-layered\r\nRegular fit (order a size up for a slouchy fit)\r\nCustomizable inside layer (the hat can’t be worn inside-out because of visible stitching)\r\nOptional custom label on the inside (1″ × 2.5″)\r\nWash at 86°F (30°C)\r\nPrinted, cut, and hand-sewn by our expert in-house teams\r\nFabric is OEKO-TEX 100 standard certified\r\nProduct code: #660\r\n\r\nThis product is made on demand. No minimums.',13.00,NULL,300,'products/tiPbs56iDByLcH02DUDYCT5bEwgZlUt8N2SY9Nsw.jpg',NULL,1,1,1,'{\"left\":0.4,\"top\":0.1,\"width\":0.2,\"height\":0.2}','2026-05-11 19:33:46','2026-05-14 15:18:31'),(11,5,'variable','[{\"key\":\"size\",\"label\":\"Size\",\"values\":[\"One Size\"]},{\"key\":\"color\",\"label\":\"Color\",\"values\":[\"Baby Pink\",\"Black\",\"Brown\",\"Dark Grey\",\"Gold\",\"Heather Greay\",\"Navy\",\"Olive\",\"Red\",\"Royal\",\"Spruce\",\"White\"]}]','Cuffed Beanie | Yupoong 1501KC','cuffed-beanie-yupoong-1501kc','CUFFEDBEANIEYUPOONG1501KC','This Cuffed Beanie is snug and form-fitting, making it a comfy choice. It’s not only warm headwear but also serves as a staple in anyone’s wardrobe during cold weather.\r\n\r\n100% Turbo acrylic fabric\r\nUnisex style\r\n12″ (30 cm) in length\r\nHypoallergenic\r\nHand washable\r\nBlank product sourced from Vietnam, Bangladesh or the Republic of Korea\r\nThis product is made on-demand. No minimums.\r\n\r\nThe beanie in Heather Grey can slightly differ in color from batch to batch. This is due to the mélange yarn fibers used in this color production.',13.00,NULL,1199,'products/LpBciABDQMeWPBKdMlKjsTZK84zrg3buooFnFvVA.webp',NULL,1,1,1,'{\"left\":0.3,\"top\":0.1,\"width\":0.4,\"height\":0.4}','2026-05-11 19:47:05','2026-05-14 15:22:50'),(12,5,'variable','[{\"key\":\"color\",\"label\":\"Color\",\"values\":[\"Athletic Heather\",\"Black\",\"Cypress\",\"Ecru\",\"Gold\",\"petrol Blue\",\"Red\",\"Walnut\"]}]','Fisherman Beanie | AS Colour 1120','fisherman-beanie-as-colour-1120','FISHERMANBEANIEASCOLOUR1120','This thick, ribbed knit fisherman-style beanie will assure warmth and comfort. Whether out in the deep waters or navigating city streets, its style will fit most environments, keeping you cozy and trendy. Thanks to its texture and multiple color choices, this is the ideal canvas for your next embroidery design. Order for yourself or sell it online!\r\n\r\n100% acrylic\r\nWide, ribbed knit\r\nSnug, comfortable fit\r\nVersatile style suitable for different outfits\r\nOne size fits most\r\nBlank product sourced from China\r\nThis product is made on demand. No minimums.',16.00,NULL,800,'products/6nZr4E50Th8q0cxpCsrflb2q5hjRMfTfdWkKRXFP.webp',NULL,1,1,1,'{\"left\":0.3,\"top\":0.1,\"width\":0.4,\"height\":0.4}','2026-05-11 22:13:23','2026-05-14 15:24:18'),(13,5,'variable','[{\"key\":\"size\",\"label\":\"Size\",\"values\":[\"One Size\"]},{\"key\":\"color\",\"label\":\"Coloe\",\"values\":[\"Black\",\"DrakGreen\",\"Gray\",\"Navy\",\"Red\",\"White\"]}]','Knit Beanie | Otto Cap 82-480','knit-beanie-otto-cap-82-480','KNITBEANIEOTTOCAP82480','This Knit Beanie has a classic shape that’s perfect for highlighting your embroidery designs. The snug fit ensures both warmth and comfort, while the cotton and acrylic blend creates a soft and pleasant feel.\r\n\r\n60% cotton, 40% acrylic\r\nBreathable cotton blend\r\nForm-fitting shape\r\nOne size fits most\r\nBlank product sourced from China\r\nThis product is made on demand. No minimums.',13.00,NULL,600,'products/4r0H1vqIcd9k7kr0IVB2hz3xx9J6BbOI2rBgn8Ks.webp',NULL,1,1,1,'{\"left\":0.3,\"top\":0.1,\"width\":0.4,\"height\":0.4}','2026-05-11 22:30:58','2026-05-14 15:25:49'),(14,5,'variable','[{\"key\":\"size\",\"label\":\"Size\",\"values\":[\"One Size\"]},{\"key\":\"color\",\"label\":\"Color\",\"values\":[\"Custom\"]}]','Knitted Beanie','knitted-beanie','KNITTEDBEANIE','This isn’t just any beanie—it’s your design, custom-knitted. Personalize every detail, from colors to patterns, and create something outstanding. Soft and lightweight, this beanie is made for colder weather and in-between seasons. Design and order one for yourself or start selling it online.\r\n\r\n55% cotton, 45% polyester\r\n4-color jacquard knit\r\n36 yarn color options\r\nLightweight, soft-feel fabric\r\nMachine washable\r\nOne size fits all\r\nKnitted on demand, fully customizable\r\nBlank product sourced and fulfilled in China\r\nDisclaimers:\r\n\r\nDue to the design’s color combinations, individual colors might appear slightly different in real life compared to the mockup.\r\nThe beanie may shrink slightly after the first wash.\r\nFor best results, follow the care instructions and wash at 30–40°C.\r\nDue to the knitting technique, the average fulfillment time for this product is 7–12 business days from Jan–Oct and 9–16 business days from Nov–Dec. Shipping can take up to 3 weeks, depending on the destination. If you’re selling this item online, we recommend informing your customers about the extended processing and delivery times.\r\nImportant: This product is available in Australia, Austria, Belgium, Canada, China, Croatia, Czech Republic, Denmark, Estonia, Finland, France, Germany, Hong Kong, Hungary, Iceland, Ireland, Italy, Japan, Latvia, Liechtenstein, Lithuania, Luxembourg, Mexico, Netherlands, New Zealand, Norway, Poland, Portugal, Singapore, Slovakia, Slovenia, Spain, Sweden, Switzerland, Taiwan, the United Kingdom, and the United States. If your shipping address is outside these regions, please choose a different product.\r\n\r\nThis product is made on demand. No minimums.',36.00,NULL,99,'products/Z6PoLi8uZdYFFft2oQK5WWE42Sd2UDKgSAYn6S4j.webp',NULL,1,0,1,'{\"left\":0.3,\"top\":0.2,\"width\":0.4,\"height\":0.4}','2026-05-11 22:37:57','2026-05-14 15:29:45'),(15,5,'variable','[{\"key\":\"size\",\"label\":\"Size\",\"values\":[\"One Size\"]},{\"key\":\"color\",\"label\":\"Color\",\"values\":[\"Acid Green\",\"Beige\",\"Black\",\"Light Blue\",\"Light Grey Melange\",\"Mustard\",\"Navy\",\"Olive\"]}]','Organic Ribbed Beanie | Atlantis','organic-ribbed-beanie-atlantis','ORGANICRIBBEDBEANIEATLANTIS','The Organic Ribbed Beanie has a classic look, but the ribbed fabric brings a pinch of uniqueness. Wear this 100% organic cotton beanie during your outdoor adventures or combine it with a streetwear outfit. Thanks to its stylish look and practicality, it’ll work for both!\r\n\r\n100% certified organic cotton\r\nAntiallergic and natural fabric\r\nCuffed beanie\r\nTear-away tag\r\nThe organic cotton content of this product is certified under GOTS (Global Organic Textile Standard)\r\nBlank product sourced from China\r\nTo learn more about eco-friendly product certificates, check out this FAQ article!\r\n\r\nThis product is made on demand. No minimums.',15.00,NULL,800,'products/b0UsdZ95eVbZc41Q7sqauvniqPpCHYzBhA0dLrNi.webp',NULL,1,0,1,'{\"left\":0.3,\"top\":0.2,\"width\":0.4,\"height\":0.4}','2026-05-11 22:52:12','2026-05-14 15:30:50'),(16,5,'variable','[{\"key\":\"size\",\"label\":\"Size\",\"values\":[\"One Size\"]},{\"key\":\"color\",\"label\":\"Color\",\"values\":[\"Black\",\"Burgundy\",\"French Navy\",\"Graphite Grey\",\"Moss Green\",\"White\"]}]','Pom-Pom Beanie | Beechfield B426','pom-pom-beanie-beechfield-b426','POMPOMBEANIEBEECHFIELDB426','Get ready for the cold season with this Pom-Pom Beanie! This classic silhouette beanie is incredi