INSERT INTO `settings` VALUES (1,'general.site_name','Pro Print Contractors','2026-05-06 14:17:43','2026-05-06 14:17:43'),(2,'general.phone','+1 (555) 123-4567','2026-05-06 14:17:44','2026-05-06 14:17:44'),(3,'general.email','hello@proprintcontractors.test','2026-05-06 14:17:44','2026-05-06 14:17:44'),(4,'general.address','123 Print Lane\r\nContractor City, ST 12345','2026-05-06 14:17:44','2026-05-06 14:28:01'),(5,'shipping.tax_rate','0','2026-05-06 14:17:44','2026-05-06 14:17:44'),(6,'shipping.flat_rate','9.99','2026-05-06 14:17:44','2026-05-06 14:17:44'),(7,'shipping.free_shipping_minimum','','2026-05-06 14:17:44','2026-05-06 14:17:44'),(8,'shop.currency','usd','2026-05-06 14:17:44','2026-05-06 14:17:44'),(9,'seo.meta_title','Pro Print Contractors — Print & Branding','2026-05-06 14:17:44','2026-05-06 14:17:44'),(10,'seo.meta_description','Premium print on demand, branding and digital services for contractors.','2026-05-06 14:17:44','2026-05-06 14:17:44'),(11,'seo.meta_keywords','print, contractors, branding, signage','2026-05-06 14:17:44','2026-05-06 14:17:44'),(12,'email.welcome.subject','Welcome to {{site_name}}','2026-05-06 14:17:44','2026-05-06 14:17:44'),(13,'email.welcome.body_html','<p>Hi {{user_name}},</p>\n<p>Thanks for creating an account at <strong>{{site_name}}</strong>.</p>\n<p>If you have questions, reply to this email or reach us at {{support_email}}.</p>\n<p>— {{site_name}}</p>','2026-05-06 14:17:44','2026-05-06 14:17:44'),(14,'email.password_reset.subject','Reset your {{site_name}} password','2026-05-06 14:17:44','2026-05-06 14:17:44'),(15,'email.password_reset.body_html','<p>Hi {{user_name}},</p>\n<p>We received a request to reset your password. Click the link below to choose a new password:</p>\n<p><a href=\"{{reset_url}}\">Reset password</a></p>\n<p>If you did not request this, you can ignore this email.</p>\n<p>— {{site_name}}</p>','2026-05-06 14:17:45','2026-05-06 14:17:45'),(16,'email.order_confirmation.subject','Order {{order_number}} confi